From 8191dd698a6c5e6a72f9b291d5bf6bf2753fb5a1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:14:51 +0100
Subject: [PATCH] kded: Unmute a device at 0% by raising its volume with the
 Mute key

Lowering the volume to 0 mutes the device, and pressing Mute then only
toggled global mute, which left it muted with the same OSD. If the device
is at 0%, the Mute key now raises its volume by one step and unmutes it.

BUG: 506791
---
 src/kded/audioshortcutsservice.cpp | 6 ++++++
 1 file changed, 6 insertions(+)

diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..7c956d5e 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -169,8 +169,14 @@ AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVaria
     muteAction->setText(i18n("Mute"));
     muteAction->setShortcut(Qt::Key_VolumeMute);
     connect(muteAction, &QAction::triggered, this, [this]() {
+        auto sink = m_preferredDevice.sink();
         if (m_globalConfig->globalMuteSinks()) {
             disableGlobalSinkMute();
+        } else if (sink && volumePercent(sink->volume()) == 0) {
+            // Lowering the volume to 0 mutes the device, so unmute it by raising the volume again
+            int percent = changeVolumePercent(sink, m_globalConfig->volumeStep());
+            showMute(percent);
+            playFeedback(-1);
         } else {
             enableGlobalSinkMute();
         }
